#!/usr/bin/env node
// Operation ASCEND B2.8 worker. A thin, supervised driver: all policy, leasing and execution happen server-side in the
// admin app under a scoped worker identity. This process only paces requests, reports its load and shuts down cleanly.
//
// Environment:
//   ASCEND_WORKER_URL           Admin worker endpoint, e.g. http://127.0.0.1:3301/api/ascend/worker (loopback HTTP or HTTPS only)
//   ASCEND_WORKER_TOKEN         Scoped worker token (asc_...). Never logged.
//   ASCEND_WORKER_ID            Stable identifier for this process (default: hostname-pid)
//   ASCEND_WORKER_CONCURRENCY   Parallel lanes, 1-8 (default 1)
//   ASCEND_WORKER_IDLE_MS       Base pause when no work is due (default 15000)
// Flags: --once (one tick per lane, then exit; for smoke tests)
import os from "node:os"
import { pathToFileURL } from "node:url"

export const VERSION = "b2.8.0"

export function loadConfig(env = process.env, argv = process.argv.slice(2)) {
  const problems = []
  let url
  try { url = new URL(env.ASCEND_WORKER_URL ?? "") } catch { problems.push("ASCEND_WORKER_URL must be a URL") }
  if (url) {
    const loopback = ["127.0.0.1", "localhost", "[::1]"].includes(url.hostname)
    if (url.pathname !== "/api/ascend/worker") problems.push("ASCEND_WORKER_URL must end in /api/ascend/worker")
    if (!(url.protocol === "https:" || (url.protocol === "http:" && loopback))) problems.push("ASCEND_WORKER_URL must be HTTPS, or HTTP on loopback")
    if (url.username || url.password || url.search || url.hash) problems.push("ASCEND_WORKER_URL must not carry credentials, a query or a fragment")
  }
  const token = env.ASCEND_WORKER_TOKEN ?? ""
  if (!/^asc_[A-Za-z0-9_-]{43}$/.test(token)) problems.push("ASCEND_WORKER_TOKEN is missing or malformed")
  const workerId = env.ASCEND_WORKER_ID || `${os.hostname().replace(/[^A-Za-z0-9._-]/g, "-").slice(0, 60)}-${process.pid}`
  if (!/^[A-Za-z0-9][A-Za-z0-9._:-]{2,79}$/.test(workerId)) problems.push("ASCEND_WORKER_ID is invalid")
  const concurrency = Number(env.ASCEND_WORKER_CONCURRENCY ?? 1)
  if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 8) problems.push("ASCEND_WORKER_CONCURRENCY must be 1-8")
  const idleMs = Number(env.ASCEND_WORKER_IDLE_MS ?? 15000)
  if (!Number.isInteger(idleMs) || idleMs < 1000 || idleMs > 600000) problems.push("ASCEND_WORKER_IDLE_MS must be 1000-600000")
  return { problems, url: url?.toString(), token, workerId, concurrency, idleMs, once: argv.includes("--once") }
}

const jitter = (ms, random) => Math.round(ms / 2 + random() * (ms / 2))

/** Run until stopped. Returns a summary. `fetchImpl`, `sleep` and `random` are injectable for tests. */
export async function runWorker(config, { fetchImpl = fetch, sleep = (ms) => new Promise((r) => setTimeout(r, ms)), random = Math.random, log = console.log, signal } = {}) {
  let stopping = false, fatal = null, inFlight = 0
  const summary = { ticks: 0, executed: 0, errors: 0, stoppedBy: null }
  const stop = (reason) => { if (!stopping) { stopping = true; summary.stoppedBy = reason; log(`[ascend-worker] stopping: ${reason}`) } }
  signal?.addEventListener("abort", () => stop("signal"))
  const post = async (status) => {
    const response = await fetchImpl(config.url, {
      method: "POST",
      headers: { authorization: `Bearer ${config.token}`, "content-type": "application/json" },
      body: JSON.stringify({ workerId: config.workerId, version: VERSION, maxConcurrency: config.concurrency, inFlight, status }),
      signal: AbortSignal.timeout(65000),
    })
    const body = await response.json().catch(() => ({}))
    return { status: response.status, body }
  }
  async function lane(index) {
    let failures = 0
    while (!stopping) {
      inFlight++
      let result
      try { result = await post("active") } catch (error) { result = { status: 0, body: { error: error?.name ?? "network_error" } } } finally { inFlight-- }
      summary.ticks++
      if (result.status === 200) {
        failures = 0
        const claimed = result.body?.claimed
        if (claimed) { summary.executed++; log(`[ascend-worker] lane ${index} ${claimed.id} -> ${claimed.status}`) }
        if (config.once) return
        if (!claimed) await sleep(jitter(config.idleMs, random))
        continue
      }
      summary.errors++
      // A revoked or invalid identity, or a disabled engine, will not fix itself: stop rather than hammer the API.
      if (result.status === 401 || result.status === 403 || result.status === 404) { fatal = `http_${result.status}`; stop(`identity or engine unavailable (HTTP ${result.status})`); return }
      if (config.once) return
      failures++
      const backoff = Math.min(300000, 2000 * 2 ** Math.min(failures, 8))
      log(`[ascend-worker] lane ${index} HTTP ${result.status || "network"}; retrying in ~${Math.round(backoff / 1000)}s`)
      await sleep(jitter(backoff, random))
    }
  }
  log(`[ascend-worker] ${config.workerId} v${VERSION} starting ${config.concurrency} lane(s)`)
  await Promise.all(Array.from({ length: config.concurrency }, (_, i) => lane(i)))
  // Tell the command centre this worker is gone, so it is not shown as stale. Best effort.
  if (!fatal) { try { await post("stopped") } catch { /* the heartbeat will simply age out */ } }
  return { ...summary, fatal }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const config = loadConfig()
  if (config.problems.length) { for (const p of config.problems) console.error(`[ascend-worker] config: ${p}`); process.exit(2) }
  const controller = new AbortController()
  for (const sig of ["SIGTERM", "SIGINT"]) process.on(sig, () => controller.abort())
  // In-flight ticks finish (each is bounded server-side); no new ones start once a signal arrives.
  const result = await runWorker(config, { signal: controller.signal })
  console.log(`[ascend-worker] stopped after ${result.ticks} tick(s), ${result.executed} execution(s), ${result.errors} error(s)`)
  process.exitCode = result.fatal ? 1 : 0
}
#!/usr/bin/env node
// Read-only Megaton worker deployment checks. Never prints credentials or invokes a job.
//
// Disabling outbound email (MEGATON_WORKER_SEND_ENABLED) does NOT make the Megaton worker side-effect free. Each call to
// /api/megaton/worker (runMegatonWorker in admin/src/lib/server/megaton.ts) can also deliver review notifications,
// dispatch social posts, delete messages for retention, enqueue mailbox sync and process already-queued jobs, each behind
// a different switch. This preflight reports every one and blocks on any external or destructive effect that has not
// been separately authorised in MEGATON_PREFLIGHT_AUTHORISED_EFFECTS (comma-separated effect names).
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export function parseEnv(text) {
  const env = {};
  for (const line of text.split(/\r?\n/)) {
    const match = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/.exec(line);
    if (match) env[match[1]] = match[2].replace(/^['"]|['"]$/g, '');
  }
  return env;
}

/** Mirrors the gating in megaton-config.ts, megaton-growth.ts and runMegatonWorker. Keep in step with those files. */
export function megatonWorkerEffects(env) {
  const on = (k) => env[k] === 'true';
  const enabled = on('MEGATON_ENABLED'), external = on('MEGATON_EXTERNAL_ENABLED'), stopped = env.MEGATON_STOP !== 'false';
  const live = enabled && !stopped;
  const mailbox = ['MEGATON_MAILCOW_HOST', 'MEGATON_MAILCOW_USER', 'MEGATON_MAILCOW_PASSWORD', 'MEGATON_MAILCOW_FROM'].every((k) => !!env[k]?.trim());
  const retentionDays = Number(env.MEGATON_MESSAGE_RETENTION_DAYS ?? 0);
  return [
    { name: 'review_notifications', kind: 'external', active: on('MEGATON_NOTIFICATIONS_ENABLED') && live && external, gate: 'MEGATON_NOTIFICATIONS_ENABLED + MEGATON_ENABLED + MEGATON_EXTERNAL_ENABLED + MEGATON_STOP=false', note: 'Independent of every send switch.' },
    { name: 'social_dispatch', kind: 'external', active: live && external && on('MEGATON_SEND_ENABLED') && on('MEGATON_SOCIAL_SEND_ENABLED'), gate: 'MEGATON_SEND_ENABLED + MEGATON_SOCIAL_SEND_ENABLED (+ enabled, external, not stopped)' },
    { name: 'outbox_email_dispatch', kind: 'external', active: on('MEGATON_WORKER_SEND_ENABLED'), gate: 'MEGATON_WORKER_SEND_ENABLED (and megaton.approve on the worker identity)' },
    { name: 'message_retention_delete', kind: 'destructive', active: live && Number.isInteger(retentionDays) && retentionDays > 0, gate: 'MEGATON_MESSAGE_RETENTION_DAYS > 0 (+ enabled, not stopped)', note: 'Deletes megaton_messages rows; irreversible.' },
    { name: 'mailbox_sync', kind: 'inbound', active: live && external && mailbox, gate: 'MEGATON_ENABLED + MEGATON_EXTERNAL_ENABLED + MEGATON_STOP=false + all MEGATON_MAILCOW_* set', note: 'Reads the company mailbox into the database.' },
    { name: 'queued_job_processing', kind: 'inbound', active: live && external, gate: 'MEGATON_ENABLED + MEGATON_EXTERNAL_ENABLED + MEGATON_STOP=false', note: 'Runs jobs founders already queued (for example mail sync).' },
  ];
}

export function preflight(env, expectedPort) {
  const results = [];
  const check = (label, ok, level = 'FAIL') => results.push({ label, status: ok ? 'PASS' : level });
  check('Worker token present', /^[A-Za-z0-9_-]{43,256}$/.test(env.MEGATON_WORKER_TOKEN || ''));
  check('Worker digest matches', !!env.MEGATON_WORKER_TOKEN && createHash('sha256').update(env.MEGATON_WORKER_TOKEN).digest('hex') === env.MEGATON_WORKER_TOKEN_SHA256);
  check('Worker identity configured', !!env.MEGATON_WORKER_ADMIN_ID && /^\d+$/.test(env.MEGATON_WORKER_SESSION_VERSION || ''));
  let url; try { url = new URL(env.MEGATON_WORKER_URL); } catch { /* reported below */ }
  check('Worker URL is loopback HTTP or HTTPS', !!url && url.pathname === '/api/megaton/worker' && (url.protocol === 'https:' || (url.protocol === 'http:' && ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname))));
  if (expectedPort) check(`Worker URL targets intended admin port ${expectedPort}`, !!url && url.port === String(expectedPort));
  check('ASCEND B2.7 founder automation view not enabled by the worker environment', env.ASCEND_AUTOMATION_ENABLED !== 'true');
  const authorised = new Set((env.MEGATON_PREFLIGHT_AUTHORISED_EFFECTS || '').split(',').map((s) => s.trim()).filter(Boolean));
  const effects = megatonWorkerEffects(env);
  for (const e of effects) {
    if (!e.active) { check(`Effect ${e.name} inactive`, true); continue; }
    if (e.kind === 'inbound') { check(`Effect ${e.name} ACTIVE (${e.kind})`, false, 'WARN'); continue; }
    check(`Effect ${e.name} ACTIVE (${e.kind})${authorised.has(e.name) ? ' and explicitly authorised' : ' without authorisation'}`, authorised.has(e.name));
  }
  const failures = results.filter((r) => r.status === 'FAIL').length;
  return { results, effects, failures };
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const envPath = process.argv[2];
  if (!envPath) { console.error('Usage: node worker-preflight.mjs /path/to/release/.env [expected-admin-port]'); process.exit(2); }
  const { results, effects, failures } = preflight(parseEnv(readFileSync(envPath, 'utf8')), process.argv[3]);
  for (const r of results) console.log(`${r.status} ${r.label}`);
  console.log('\nEffects a worker invocation can perform (values are never printed):');
  for (const e of effects) console.log(`  ${e.active ? 'ON ' : 'off'} ${e.name.padEnd(26)} ${e.kind.padEnd(11)} gate: ${e.gate}${e.note ? ` - ${e.note}` : ''}`);
  console.log(failures ? `\nBLOCKED: ${failures} failed preflight check(s)` : '\nStatic preflight passed; database/session checks still required');
  process.exitCode = failures ? 1 : 0;
}

